$("#filterBtn").onclick=()=>$("#filterPanel").classList.toggle("open");$("#showLate").onclick=()=>{showView("transactions");applyFilters("late")};$$(".tabs button").forEach(b=>b.onclick=()=>{$$(".tabs button").forEach(x=>x.classList.remove("active"));b.classList.add("active");activeFilter=b.dataset.filter;applyFilters()});const searchFields={nameFilter:"name",subjectFilter:"subject",entityFilter:"entity",identityFilter:"identity",referenceFilter:"reference",fromFilter:"from",toFilter:"to"};async function applyFilters(force){const p=new URLSearchParams(),k=force||activeFilter;if(k==="incoming")p.set("type","وارد");if(k==="outgoing")p.set("type","صادر");if(k==="late")p.set("status","متأخرة");if($("#deptFilter").value!=="all")p.set("department",$("#deptFilter").value);if($("#statusFilter").value!=="all")p.set("status",$("#statusFilter").value);if($("#priorityFilter").value!=="all")p.set("priority",$("#priorityFilter").value);Object.entries(searchFields).forEach(([id,key])=>{const value=$("#"+id).value.trim();if(value)p.set(key,value)});await loadTransactions("?"+p)}["#deptFilter","#statusFilter","#priorityFilter"].forEach(s=>$(s).onchange=()=>applyFilters());$("#applySearch").onclick=()=>applyFilters();Object.keys(searchFields).forEach(id=>$("#"+id).onkeydown=e=>{if(e.key==="Enter")applyFilters()});$("#identityFilter").oninput=e=>e.target.value=e.target.value.replace(/\D/g,"").slice(0,10);$("#resetFilters").onclick=()=>{$("#deptFilter").value=$("#statusFilter").value=$("#priorityFilter").value="all";Object.keys(searchFields).forEach(id=>$("#"+id).value="");activeFilter="all";loadTransactions()};
